INSERT INTO `dc_affix_tunables` (`affix_name`, `parameter`, `d3_value`, `tuned_value`, `unit`, `notes`) VALUES
('_global', 'cast_interval', NULL, 6.0, 'seconds', '13-elite-affixes: D3 publishes no cast cadence for any affix but Mortar. The designer''s tunable, accepted 2026-09-08.'),
('_global', 'tick_interval', NULL, 1.0, 'seconds', 'How often a ground zone hurts what is standing in it. Ours, not D3''s.'),
('_global', 'proc_chance', NULL, 20.0, 'percent', 'Shared on-hit proc chance for Knockback and Nightmarish. The designer''s tunable; the wiki gives a chance with no value.'),
('_global', 'damage_ground_tick', NULL, 0.5, 'multiplier', 'PROVISIONAL. 13-elite-affixes section 9 defers what affix damage is a fraction of; this is a multiple of the elite''s own average swing so an affix can be tested at all.'),
('_global', 'damage_burst', NULL, 2.0, 'multiplier', 'PROVISIONAL, see damage_ground_tick.'),
('_global', 'damage_discharge', NULL, 0.75, 'multiplier', 'PROVISIONAL, see damage_ground_tick.'),
('_global', 'minion_spread', NULL, 5.0, 'yards', 'How far a summoned pack member or illusion is placed from the body it came from. Ours.'),
('_global', 'rare_minions_min', NULL, 2.0, 'count', '09-rifts section 2 step 2: a rare pack''s base minion count. Horde doubles it.'),
('_global', 'rare_minions_max', NULL, 4.0, 'count', '09-rifts section 2 step 2: a rare pack''s base minion count. Horde doubles it.'),
('_global', 'knockback_speed_z', NULL, 10.0, 'yards per second', 'The vertical speed the displacement parabola is solved on; docs/research/knockback-speeds.md. Shared by Knockback and Vortex.'),
('_global', 'offensive_min', 2.0, NULL, 'count', 'maxroll: an Elite will always have at least 2, at most 3 Offensive affixes.'),
('_global', 'offensive_max', 3.0, NULL, 'count', 'maxroll: an Elite will always have at least 2, at most 3 Offensive affixes.'),
('_global', 'defensive_max', 1.0, NULL, 'count', 'maxroll: cannot have more than 1 Defensive affix.'),
('_global', 'crowd_control_max', 1.0, NULL, 'count', 'maxroll: cannot have more than 1 Crowd Control affix.'),
('_global', 'level_limit_from', 60.0, NULL, 'count', 'wiki: from level 60 a pack may carry at most three of the eleven affixes flagged level_60_limited in elite_affix_pools.csv.'),
('_global', 'level_limit_max', 3.0, NULL, 'count', 'wiki: at most three of the eleven, see level_limit_from.'),
('_global', 'rift_logout_grace_seconds', NULL, 120.0, 'seconds', '09-rifts 7.9.7: how long a party member who logs out or disconnects keeps enrollment before being detached. The designer''s tunable, 2 minutes, decisions.md 2026-09-16. Solo logout closes the run at once and never waits this out.'),
('_global', 'close_xp_base', NULL, 1000.0, 'count', '09-rifts 7.9.7 closing reward: base Paragon XP paid on the first Keeper turn-in, before the tier bonus (XP = close_xp_base x (1 + tier xp_bonus_pct)). Ruling 2026-09-17: 1000 to start, tunable. 0 pays nothing and the module logs that it did. No published D3 amount exists; never fill this from memory.'),
('_global', 'close_gold_base', NULL, 1000.0, 'count', '09-rifts 7.9.7 closing reward: base gold paid on the first Keeper turn-in, before the tier bonus (gold = close_gold_base x (1 + tier gold_bonus_pct)). Ruling 2026-09-17: 1000 to start, tunable. 0 pays nothing and the module logs that it did. No published D3 amount exists; never fill this from memory.'),
('Arcane Enchanted', 'arming_delay', 2.0, NULL, 'seconds', 'maxroll: 2 sec delay after cast.'),
